package net.officefloor.hq.app.people;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.JoinTable;
import jakarta.persistence.ManyToMany;
import jakarta.persistence.Table;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person on the list: a name and whole-number "alpha", "beta" and "gamma" (each absent until
 * given), and the derived "thrust" (alpha × beta), "drift" (gamma − alpha) and "momentum"
 * (thrust + 3 × drift), which are absent until all three raw values are given. A person may have
 * any number of "patrons": other people on the list, whose thrust added together is the person's
 * "backing". A person belongs to one sheet (null for the unnamed sheet) and is numbered within it, so sheets never share people. "Net" is momentum plus backing (backing counted as zero without patrons). A person may have a
 * "grade" (LOW, MID or HIGH; absent until given), from which their "weight" is 1, 3 or 5. "Load" is momentum times weight.
 * A person may have an "onset" date (absent until given); their "age" is the complete weeks from onset to the sheet's anchor.
 * "Decay" is momentum minus age. A person is "active" or not; a new person is active. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** The person's id within their sheet; the id the user and the API see. */
    @Column(name = "local_id")
    private Long localId;

    private String name;

    private Integer alpha;

    private Integer beta;

    private Integer gamma;

    @Enumerated(EnumType.STRING)
    private Grade grade;

    private LocalDate onset;

    private boolean active = true;

    /** The id of the sheet the person belongs to; null for the unnamed sheet. */
    @Column(name = "sheet_id")
    private String sheetId;

    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(name = "person_patron", joinColumns = @JoinColumn(name = "person_id"),
            inverseJoinColumns = @JoinColumn(name = "patron_id"))
    private Set<Person> patrons = new HashSet<>();

    protected Person() {
    }

    public Person(String sheetId, long localId, String name, Integer alpha, Integer beta, Integer gamma) {
        this.sheetId = sheetId;
        this.localId = localId;
        this.name = name;
        this.alpha = alpha;
        this.beta = beta;
        this.gamma = gamma;
    }

    public Long getId() {
        return id;
    }

    public Long getLocalId() {
        return localId;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public Integer getAlpha() {
        return alpha;
    }

    public void setAlpha(Integer alpha) {
        this.alpha = alpha;
    }

    public Integer getBeta() {
        return beta;
    }

    public void setBeta(Integer beta) {
        this.beta = beta;
    }

    public Integer getGamma() {
        return gamma;
    }

    public void setGamma(Integer gamma) {
        this.gamma = gamma;
    }

    public Grade getGrade() {
        return grade;
    }

    public void setGrade(Grade grade) {
        this.grade = grade;
    }

    public boolean isActive() {
        return active;
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    public LocalDate getOnset() {
        return onset;
    }

    /** Age is the complete seven-day weeks from onset to the anchor (leftover days dropped), negative when onset is
     * after it and truncated toward zero; absent without an onset. */
    public Long getAge(LocalDate anchor) {
        return onset == null ? null : ChronoUnit.WEEKS.between(onset, anchor);
    }

    /** Decay is momentum minus age; absent while either is absent. */
    public Long getDecay(LocalDate anchor) {
        Integer momentum = getMomentum();
        Long age = getAge(anchor);
        return momentum == null || age == null ? null : momentum - age;
    }

    /** Weight comes from the grade: LOW 1, MID 3, HIGH 5; absent without a grade. */
    public Integer getWeight() {
        return grade == null ? null : grade.weight();
    }

    /** The patrons, sorted by name. */
    public List<Person> getPatrons() {
        return patrons.stream()
                .sorted(Comparator.comparing(Person::getName).thenComparing(Person::getId))
                .toList();
    }

    public void setPatrons(Set<Person> patrons) {
        this.patrons = new HashSet<>(patrons);
    }

    /** The derived values exist only once alpha, beta and gamma are all given. */
    private boolean complete() {
        return alpha != null && beta != null && gamma != null;
    }

    /** Thrust is alpha multiplied by beta; absent until alpha, beta and gamma are all given. */
    public Integer getThrust() {
        return complete() ? alpha * beta : null;
    }

    /** Drift is gamma minus alpha; absent until alpha, beta and gamma are all given. */
    public Integer getDrift() {
        return complete() ? gamma - alpha : null;
    }

    /** Momentum is thrust plus three times drift; absent while either is absent. */
    public Integer getMomentum() {
        Integer thrust = getThrust();
        Integer drift = getDrift();
        return thrust == null || drift == null ? null : thrust + 3 * drift;
    }

    /** Load is momentum times weight; absent while either is absent. */
    public Integer getLoad() {
        Integer momentum = getMomentum();
        Integer weight = getWeight();
        return momentum == null || weight == null ? null : momentum * weight;
    }

    /** Backing is the sum of the patrons' thrust; absent without patrons or while any patron's thrust is absent. */
    public Integer getBacking() {
        if (patrons.isEmpty()) {
            return null;
        }
        int sum = 0;
        for (Person patron : patrons) {
            Integer thrust = patron.getThrust();
            if (thrust == null) {
                return null;
            }
            sum += thrust;
        }
        return sum;
    }

    /** Net is momentum plus backing, counting backing as zero without patrons; absent with momentum, or with a patron whose thrust is absent. */
    public Integer getNet() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        if (patrons.isEmpty()) {
            return momentum;
        }
        Integer backing = getBacking();
        return backing == null ? null : momentum + backing;
    }

    /** Effective is net while active, and half of net rounded down while not active (absent while net is). */
    public Integer getEffective() {
        Integer net = getNet();
        if (net == null || active) {
            return net;
        }
        return Math.floorDiv(net, 2);
    }
    /** Tier classifies momentum: SINK below zero, STEADY up to 199, SURGE from 200; absent with momentum. */
    public String getTier() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        return momentum < 0 ? "SINK" : momentum <= 199 ? "STEADY" : "SURGE";
    }
}
package net.officefloor.hq.app.people;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma,
            Grade grade, Integer weight, Integer thrust, Integer drift, Integer momentum, Integer load, String tier, List<PatronView> patrons,
            Integer backing, Integer net, Integer rank, Integer percentile, LocalDate onset, Long age, Long decay, boolean active, Integer effective) {
        static PersonView of(Person p, Map<Long, Integer> ranks, LocalDate anchor) {
            Integer rank = ranks.get(p.getLocalId());
            return new PersonView(p.getLocalId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(),
                    p.getGrade(), p.getWeight(), p.getThrust(), p.getDrift(), p.getMomentum(), p.getLoad(), p.getTier(),
                    p.getPatrons().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getBacking(), p.getNet(), rank, PersonController.percentile(rank, ranks.size()), p.getOnset(),
                    p.getAge(anchor), p.getDecay(anchor), p.isActive(), p.getEffective());
        }
    }

    /**
     * A rank as a percentile of the ranked people: the best 100, the worst 0, evenly spread between
     * by rank and rounded to a whole number. A lone ranked person is 100; unranked has none.
     */
    static Integer percentile(Integer rank, int ranked) {
        if (rank == null) {
            return null;
        }
        if (ranked <= 1) {
            return 100;
        }
        return (int) Math.round((ranked - rank) * 100.0 / (ranked - 1));
    }

    /** Highest momentum first; equal momentum by higher alpha, then by name, earlier in the alphabet first. */
    private static final Comparator<Person> RANK_ORDER = Comparator
            .comparing(Person::getMomentum, Comparator.reverseOrder())
            .thenComparing(Person::getAlpha, Comparator.nullsLast(Comparator.reverseOrder()))
            .thenComparing(Person::getName)
            .thenComparing(Person::getLocalId);

    public record PatronView(Long id, String name) {
    }

    public record NewPerson(@NotBlank String name, Integer alpha, Integer beta, Integer gamma, Grade grade) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    @GetMapping
    public List<PersonView> list(@RequestParam(required = false) String sheet) {
        String sheetId = sheetId(sheet);
        List<Person> people = service.list(sheetId);
        Map<Long, Integer> ranks = ranks(people);
        LocalDate anchor = service.anchor(sheetId);
        return people.stream().map(p -> PersonView.of(p, ranks, anchor)).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@RequestParam(required = false) String sheet, @Valid @RequestBody NewPerson person) {
        return view(sheetId(sheet), service.add(sheetId(sheet), person.name(), person.alpha(), person.beta(), person.gamma(),
                person.grade()));
    }

    /**
     * Sets, on the person with this id on the request's sheet, whichever of alpha, beta, gamma, grade, active
     * (true or false) and patronIds (a list of ids on that sheet) the body names; a null value clears it.
     */
    @PatchMapping("/{id}")
    public PersonView update(@RequestParam(required = false) String sheet, @PathVariable long id,
            @RequestBody Map<String, Object> update) {
        String sheetId = sheetId(sheet);
        Optional<Person> person = service.find(sheetId, id);
        if (update.containsKey("alpha")) {
            person = service.setAlpha(sheetId, id, integer(update.get("alpha")));
        }
        if (update.containsKey("beta")) {
            person = service.setBeta(sheetId, id, integer(update.get("beta")));
        }
        if (update.containsKey("gamma")) {
            person = service.setGamma(sheetId, id, integer(update.get("gamma")));
        }
        if (update.containsKey("grade")) {
            person = service.setGrade(sheetId, id, grade(update.get("grade")));
        }
        if (update.containsKey("active")) {
            if (!(update.get("active") instanceof Boolean active)) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "active must be true or false");
            }
            person = service.setActive(sheetId, id, active);
        }
        if (update.containsKey("patronIds")) {
            List<Long> patronIds = new ArrayList<>();
            if (update.get("patronIds") instanceof List<?> ids) {
                for (Object patronId : ids) {
                    patronIds.add(integer(patronId).longValue());
                }
            } else if (update.get("patronIds") != null) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "patronIds must be a list");
            }
            try {
                person = service.setPatrons(sheetId, id, patronIds);
            } catch (IllegalArgumentException e) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage());
            }
        }
        return person.map(p -> view(sheetId, p))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
    }

    /** A person's view, ranked among the people on their sheet. */
    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, ranks(service.list(sheetId)), service.anchor(sheetId));
    }

    /**
     * Each person's rank by local id: 1 for the highest momentum, then 2, 3, ... with equal momentum
     * ordered by higher alpha, then by name. People without a momentum are not ranked.
     */
    private static Map<Long, Integer> ranks(List<Person> people) {
        List<Person> ranked = people.stream().filter(p -> p.getMomentum() != null).sorted(RANK_ORDER).toList();
        Map<Long, Integer> ranks = new HashMap<>();
        for (int i = 0; i < ranked.size(); i++) {
            ranks.put(ranked.get(i).getLocalId(), i + 1);
        }
        return ranks;
    }

    /** The sheet named by the request, trimmed; blank or absent means the unnamed sheet. */
    private static String sheetId(String sheet) {
        return sheet == null || sheet.isBlank() ? null : sheet.trim();
    }

    private static Grade grade(Object value) {
        if (value == null) {
            return null;
        }
        try {
            return Grade.parse(String.valueOf(value));
        } catch (IllegalArgumentException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage());
        }
    }

    private static Integer integer(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Integer i) {
            return i;
        }
        throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "expected a whole number, got " + value);
    }
}
import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map } from 'rxjs';

export interface Person {
  id: number;
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  grade: Grade | null;
  weight: number | null;
  thrust: number | null;
  drift: number | null;
  momentum: number | null;
  load: number | null;
  tier: string | null;
  patrons: Patron[];
  backing: number | null;
  net: number | null;
  rank: number | null;
  percentile: number | null;
  onset: string | null;
  age: number | null;
  decay: number | null;
  active: boolean;
  effective: number | null;
}

// A sheet: its id (null for the unnamed sheet) and its anchor date (yyyy-mm-dd; today when none is set).
export interface Sheet {
  id: string | null;
  anchor: string;
}

export type Grade = 'LOW' | 'MID' | 'HIGH';

export const GRADES: readonly Grade[] = ['LOW', 'MID', 'HIGH'];

export interface Patron {
  id: number;
  name: string;
}

export interface NewPerson {
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  grade: Grade | null;
}

// The people REST API (/api/people).
@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);

  // The people on a sheet; null is the unnamed sheet.
  list(sheet: string | null): Observable<Person[]> {
    return this.http.get<Person[]>('/api/people', { params: sheetParams(sheet) });
  }

  // A sheet (with its anchor); null is the unnamed sheet.
  sheet(sheet: string | null): Observable<Sheet> {
    return this.http.get<Sheet>('/api/sheet', { params: sheetParams(sheet) });
  }

  // Opens a named sheet, starting a new empty one when no sheet has that id yet.
  openSheet(sheet: string): Observable<void> {
    return this.http.put(`/api/sheets/${encodeURIComponent(sheet)}`, null).pipe(map(() => undefined));
  }

  // Adds a person to a sheet; null is the unnamed sheet.
  add(sheet: string | null, person: NewPerson): Observable<Person> {
    return this.http.post<Person>('/api/people', person, { params: sheetParams(sheet) });
  }

  // Updates the person with an id on a sheet (ids are per sheet); null is the unnamed sheet.
  update(sheet: string | null, id: number, values: Omit<NewPerson, 'name'>): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, values, { params: sheetParams(sheet) });
  }

  setAlpha(sheet: string | null, id: number, alpha: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { alpha }, { params: sheetParams(sheet) });
  }

  setBeta(sheet: string | null, id: number, beta: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { beta }, { params: sheetParams(sheet) });
  }

  setGamma(sheet: string | null, id: number, gamma: number | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { gamma }, { params: sheetParams(sheet) });
  }

  setGrade(sheet: string | null, id: number, grade: Grade | null): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { grade }, { params: sheetParams(sheet) });
  }

  setActive(sheet: string | null, id: number, active: boolean): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { active }, { params: sheetParams(sheet) });
  }

  setPatrons(sheet: string | null, id: number, patronIds: number[]): Observable<Person> {
    return this.http.patch<Person>(`/api/people/${id}`, { patronIds }, { params: sheetParams(sheet) });
  }
}

function sheetParams(sheet: string | null): HttpParams {
  return sheet === null ? new HttpParams() : new HttpParams().set('sheet', sheet);
}
import { Component, computed, inject, signal } from '@angular/core';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { GRADES, Grade, PeopleService, Person } from './people.service';

// The people list: every person with their name, alpha, beta, gamma, thrust (alpha × beta), drift
// (gamma − alpha) and momentum (thrust + 3 × drift) and its tier, plus a form to add one. Alpha, beta and
// gamma are optional on add and can be filled in (or changed) on the row later; while any is missing the
// derived values show "n/a". Each row's Edit button loads that person into the form, which then saves
// their alpha, beta and gamma instead of adding. Each person may have any number of patrons (other
// people), listed by name and chosen on the row; their backing is the sum of their patrons' thrust
// ("n/a" without patrons), and their net is momentum plus backing (counted as zero without patrons).
// Each person's rank orders the sheet by momentum, highest first (rank 1), with equal momentum ranked
// by higher alpha first, then by name; without a momentum the rank shows "n/a". The sheet's leader
// is the name of the rank-1 person ("n/a" when nobody is ranked). Each ranked person's percentile spreads the ranks evenly from
// 100 (the best) to 0 (the worst), rounded; a lone ranked person is 100.
// Each person may have a grade (LOW, MID or HIGH), chosen on add, in the edit form or on the row; their
// weight comes from it (LOW 1, MID 3, HIGH 5, "n/a" without a grade). Their load is momentum × weight
// ("n/a" while either is missing). The sheet's total load is everyone's load added together, leaving
// out anyone whose load is "n/a".
// The list shows one sheet: typing a sheet id and loading it opens that sheet, whose id is then
// shown, and people added belong to it. Until one is opened the unnamed sheet is shown. Opening an
// id no sheet has yet starts a new empty sheet with that id. Sheets are kept apart: each numbers
// its own people, and a sheet only ever shows (and edits) its own.
// The sheet shows its anchor date (today when none is set), and each person their onset date and
// their age: complete weeks from onset to the anchor, negative (toward zero) when onset is after it ("n/a" without onset).
// Their decay is momentum minus age ("n/a" while either is missing).
// Each person is active or not ("yes" or "no"; a new person is active), marked with the row's checkbox.
// Their effective is their net while active, and half their net rounded down while not active
// ("n/a" while net is).
// The sheet's active count is how many of its people are active, and its total effective is everyone's
// effective added together, leaving out anyone whose effective is "n/a".
@Component({
  selector: 'app-people',
  imports: [ReactiveFormsModule],
  template: `
    <h1>People</h1>

    <form (submit)="$event.preventDefault(); openSheet(sheetInput.value)" data-testid="sheet-form">
      <label for="sheet-id">Sheet</label>
      <input #sheetInput id="sheet-id" data-testid="sheet-id-input" />
      <button type="submit" data-testid="sheet-load">Open sheet</button>
    </form>
    <p>
      Open sheet:
      @if (sheet() !== null) {
        <strong data-testid="sheet-current-id">{{ sheet() }}</strong>
      } @else {
        <span data-testid="sheet-none">none</span>
      }
    </p>
    <p>Anchor: <strong data-testid="sheet-anchor">{{ anchor() }}</strong></p>

    <form [formGroup]="form" (ngSubmit)="submit()" data-testid="person-form">
      <label for="person-name">Name</label>
      <input id="person-name" formControlName="name" data-testid="person-form-name" />
      <label for="person-alpha">Alpha</label>
      <input
        id="person-alpha"
        type="number"
        step="1"
          <th scope="col">Grade</th>
          <th scope="col">Active</th>
          <th scope="col">Onset</th>
          <th scope="col">Age</th>
          <th scope="col">Decay</th>
          <th scope="col">Weight</th>
          <th scope="col">Thrust</th>
          <th scope="col">Drift</th>
          <th scope="col">Momentum</th>
          <th scope="col">Load</th>
          <th scope="col">Tier</th>
          <th scope="col">Patrons</th>
          <th scope="col">Backing</th>
          <th scope="col">Net</th>
          <th scope="col">Effective</th>
          <th scope="col">Rank</th>
          <th scope="col">Percentile</th>
          <th scope="col">Set alpha</th>
          <th scope="col">Set beta</th>
          <th scope="col">Set gamma</th>
          <th scope="col">Set grade</th>
          <th scope="col">Set active</th>
          <th scope="col">Set patrons</th>
          <th scope="col">Edit</th>
        </tr>
      </thead>
      <tbody>
        @for (p of people(); track p.id) {
          <tr [attr.data-testid]="'person-row-' + p.id">
            <td data-testid="person-name">{{ p.name }}</td>
            <td data-testid="person-alpha">{{ p.alpha }}</td>
            <td data-testid="person-beta">{{ p.beta }}</td>
            <td data-testid="person-gamma">{{ p.gamma }}</td>
            <td data-testid="person-grade">{{ p.grade }}</td>
            <td data-testid="person-active">{{ p.active ? 'yes' : 'no' }}</td>
            <td data-testid="person-onset">{{ p.onset }}</td>
            <td data-testid="concept-age">{{ p.age ?? 'n/a' }}</td>
            <td data-testid="concept-decay">{{ p.decay ?? 'n/a' }}</td>
            <td data-testid="concept-weight">{{ p.weight ?? 'n/a' }}</td>
            <td data-testid="concept-thrust">{{ p.thrust ?? 'n/a' }}</td>
            <td data-testid="concept-drift">{{ p.drift ?? 'n/a' }}</td>
            <td data-testid="concept-momentum">{{ p.momentum ?? 'n/a' }}</td>
            <td data-testid="concept-load">{{ p.load ?? 'n/a' }}</td>
            <td data-testid="concept-tier">{{ p.tier ?? 'n/a' }}</td>
            <td data-testid="person-patrons">{{ patronNames(p) }}</td>
            <td data-testid="concept-backing">{{ p.backing ?? 'n/a' }}</td>
            <td data-testid="concept-net">{{ p.net ?? 'n/a' }}</td>
            <td data-testid="concept-effective">{{ p.effective ?? 'n/a' }}</td>
            <td data-testid="concept-rank">{{ p.rank ?? 'n/a' }}</td>
            <td data-testid="concept-percentile">{{ p.percentile ?? 'n/a' }}</td>
            <td>
              <form (submit)="$event.preventDefault(); setAlpha(p, alphaInput.value)">
                <label class="visually-hidden" [for]="'person-alpha-edit-' + p.id">
                  Alpha for {{ p.name }}
                </label>
                <input
                  #alphaInput
                  [id]="'person-alpha-edit-' + p.id"
                  type="number"
                  step="1"
                  [value]="p.alpha ?? ''"
                  data-testid="person-alpha-input"
                />
                <button type="submit" data-testid="person-alpha-save">Save</button>
              </form>
            </td>

